ALTER TABLE accounts ADD COLUMN status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled'));
ALTER TABLE accounts ADD COLUMN status_revision bigint NOT NULL DEFAULT 1;
ALTER TABLE cloud_conversations ALTER COLUMN first_id DROP NOT NULL;
ALTER TABLE cloud_conversations ALTER COLUMN second_id DROP NOT NULL;
ALTER TABLE cloud_conversations ADD COLUMN kind text NOT NULL DEFAULT 'direct' CHECK(kind IN ('direct','group'));
ALTER TABLE cloud_conversations ADD COLUMN name text NOT NULL DEFAULT '';
ALTER TABLE cloud_conversations ADD CONSTRAINT conversation_shape CHECK ((kind='direct' AND first_id IS NOT NULL AND second_id IS NOT NULL) OR (kind='group' AND first_id IS NULL AND second_id IS NULL));
CREATE TABLE cloud_members(conversation uuid NOT NULL REFERENCES cloud_conversations(id), account_id uuid NOT NULL REFERENCES accounts(id), role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','admin','member')), PRIMARY KEY(conversation,account_id));
CREATE UNIQUE INDEX cloud_group_owner ON cloud_members(conversation) WHERE role='owner';
CREATE INDEX cloud_members_account ON cloud_members(account_id,conversation);
INSERT INTO cloud_members(conversation,account_id) SELECT id,first_id FROM cloud_conversations UNION ALL SELECT id,second_id FROM cloud_conversations;
ALTER TABLE cloud_contacts ADD COLUMN listed boolean NOT NULL DEFAULT true;
ALTER TABLE cloud_contacts ADD COLUMN blocked boolean NOT NULL DEFAULT false;
ALTER TABLE cloud_contacts ADD COLUMN revision bigint NOT NULL DEFAULT 1;
ALTER TABLE cloud_messages ADD COLUMN sender_name text NOT NULL DEFAULT '';
UPDATE cloud_messages m SET sender_name=a.name FROM accounts a WHERE a.id=m.sender;
ALTER TABLE cloud_messages ADD COLUMN reply_to uuid REFERENCES cloud_messages(id);
ALTER TABLE cloud_messages ADD COLUMN mentions uuid[] NOT NULL DEFAULT '{}';
ALTER TABLE cloud_messages ADD COLUMN ai_responses jsonb NOT NULL DEFAULT '[]';
UPDATE cloud_messages m SET ai_responses=jsonb_build_array(ai_response || jsonb_build_object('aiId',t.ai_id)) FROM cloud_node_tasks t WHERE t.input_id=m.id AND m.ai_response IS NOT NULL;
ALTER TABLE cloud_messages DROP COLUMN ai_response;
ALTER TABLE cloud_node_tasks ADD COLUMN queue_position bigserial UNIQUE;
ALTER TABLE cloud_node_tasks ADD COLUMN conversation_revision bigint NOT NULL DEFAULT 1;
CREATE INDEX cloud_node_queue ON cloud_node_tasks(conversation,queue_position) WHERE state IN ('queued','running');
CREATE TABLE cloud_group_receipts(owner uuid NOT NULL REFERENCES accounts(id), request uuid NOT NULL, fingerprint text NOT NULL, conversation uuid REFERENCES cloud_conversations(id), PRIMARY KEY(owner,request));
